```javascript
import { 
  MeshBasicNodeMaterial, 
  MeshStandardNodeMaterial, 
  InstancedMesh, 
  BufferGeometry, 
  IcosahedronGeometry, 
  PlaneGeometry,
  Group, 
  Color, 
  Matrix4, 
  Vector3, 
  Quaternion,
  DoubleSide,
  Fog
} from 'three/webgpu';
import { vec3, mix, smoothstep, uniform, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group: ThreeGroup, Mesh: ThreeMesh, Color: ThreeColor } = ctx.THREE;
  const group = new ThreeGroup();

  // Keep track of GSAP timelines and primitives for cleanup
  const activeTimelines = [];
  const activePrimitives = [];

  // --- STAGE BACKDROP (Dark gradient to prevent FLAT_VOID) ---
  const backdropGeo = new PlaneGeometry(16, 12);
  const backdropMat = new MeshBasicNodeMaterial({
    side: DoubleSide,
    depthWrite: false
  });

  // Create a vertical gradient matching the spec: top #16161d (ink) to bottom #0b0b10 (background)
  const uBotColor = uniform(new ThreeColor('#0b0b10'));
  const uTopColor = uniform(new ThreeColor('#16161d'));
  const vUv = positionLocal.xy; 
  backdropMat.colorNode = mix(uBotColor, uTopColor, vUv.y.add(0.5));

  const backdrop = new ThreeMesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -5);
  group.add(backdrop);

  // --- PARTICLES DATA & CONFIG ---
  const numOuter = 1200;
  const numCore = 90;
  const totalParticles = numOuter + numCore;

  const particleGeo = new IcosahedronGeometry(0.012, 1);
  const particleMat = new MeshStandardNodeMaterial({
    roughness: 1.0,
    metalness: 0.0,
    color: new ThreeColor('#e8ecf2'),
    emissive: new ThreeColor('#e8ecf2'),
    emissiveIntensity: 0.9,
    transparent: true
  });

  const coreMat = new MeshStandardNodeMaterial({
    roughness: 0.2,
    metalness: 0.1,
    color: new ThreeColor('#ff2a38'),
    emissive: new ThreeColor('#ff2a38'),
    emissiveIntensity: 1.8,
    transparent: true,
    blending: 2 // Additive
  });

  const instancedMesh = new InstancedMesh(particleGeo, particleMat, numOuter);
  const coreInstancedMesh = new InstancedMesh(particleGeo, coreMat, numCore);

  group.add(instancedMesh);
  group.add(coreInstancedMesh);

  // Particle tracking arrays
  const outerParticles = [];
  const coreParticles = [];

  const tempMatrix = new Matrix4();
  const tempPos = new Vector3();
  const tempScale = new Vector3(1, 1, 1);
  const tempRot = new Quaternion();

  // Helper distribution functions
  function getEllipsoidPoint(rx, ry, rz) {
    const u = Math.random();
    const v = Math.random();
    const theta = u * 2.0 * Math.PI;
    const phi = Math.acos(2.0 * v - 1.0);
    return new Vector3(
      rx * Math.sin(phi) * Math.cos(theta),
      ry * Math.sin(phi) * Math.sin(theta),
      rz * Math.cos(phi) - 1.5 // shell centered around z=-1.5
    );
  }

  function getSpherePoint(radius) {
    const u = Math.random();
    const v = Math.random();
    const theta = u * 2.0 * Math.PI;
    const phi = Math.acos(2.0 * v - 1.0);
    const r = radius * Math.pow(Math.random(), 0.3); // Core concentrated at center
    return new Vector3(
      r * Math.sin(phi) * Math.cos(theta),
      r * Math.sin(phi) * Math.sin(theta),
      r * Math.cos(phi)
    );
  }

  // Populate outer particles
  for (let i = 0; i < numOuter; i++) {
    const anchor = getEllipsoidPoint(3.0, 2.0, 2.5);

    // Depth falloff logic: opacity 0.9 at z=0 to 0.15 at z=-5
    let opacity = 0.9;
    if (anchor.z <= 0) {
      const t = Math.min(Math.max(-anchor.z / 5.0, 0), 1);
      opacity = 0.9 - t * (0.9 - 0.15);
    }

    outerParticles.push({
      anchor: anchor,
      currentPos: new Vector3(0, 0, 0),
      scale: 0.0,
      phaseOffset: Math.random() * Math.PI * 2,
      opacity: opacity
    });
  }

  // Populate core particles
  for (let i = 0; i < numCore; i++) {
    const anchor = getSpherePoint(0.5);
    coreParticles.push({
      anchor: anchor,
      currentPos: new Vector3(0, 0, 0),
      scale: 0.0,
      phaseOffset: Math.random() * Math.PI * 2,
      opacity: 1.0
    });
  }

  // Set initial Matrices
  updateInstanceMatrices();

  // Instancement Updater helper
  function updateInstanceMatrices() {
    for (let i = 0; i < numOuter; i++) {
      const p = outerParticles[i];
      tempPos.copy(p.currentPos);
      tempScale.setScalar(p.scale);
      tempMatrix.compose(tempPos, tempRot, tempScale);
      instancedMesh.setMatrixAt(i, tempMatrix);
    }
    instancedMesh.instanceMatrix.needsUpdate = true;

    for (let i = 0; i < numCore; i++) {
      const p = coreParticles[i];
      tempPos.copy(p.currentPos);
      tempScale.setScalar(p.scale);
      tempMatrix.compose(tempPos, tempRot, tempScale);
      coreInstancedMesh.setMatrixAt(i, tempMatrix);
    }
    coreInstancedMesh.instanceMatrix.needsUpdate = true;
  }

  // --- TEXT CREATION (MSDF) ---
  const heroText = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 0.62, // Scaled down to fit Scene units from design tokens
    color: '#e8ecf2',
    align: 'center'
  });
  heroText.position.set(0, 0.5, 0.5);
  group.add(heroText);

  const subheadText = ctx.fontAtlas.createText('Precision instruments for the dark hours.', {
    fontSize: 0.20,
    color: '#e8ecf2',
    align: 'center'
  });
  subheadText.position.set(0, -0.25, 0.5);
  group.add(subheadText);

  const captionText = ctx.fontAtlas.createText('EST. 2019 / GENEVA AND KYOTO', {
    fontSize: 0.09,
    color: '#ff2a38', // Accent core tie-in
    align: 'center'
  });
  captionText.position.set(0, -2.25, 0.5);
  group.add(captionText);

  // --- LIGHTING ---
  // Create localized studio accent light pointing right at core
  const coreRimLight = new ctx.THREE.PointLight('#ff2a38', 1.4, 6);
  coreRimLight.position.set(2, 2, 2);
  group.add(coreRimLight);

  // --- ANIMATIONS & DRIFT SYSTEM ---
  const dynamicTimeline = gsap.timeline();
  activeTimelines.push(dynamicTimeline);

  // Core Pulse
  dynamicTimeline.to(coreMat, {
    emissiveIntensity: 1.5,
    duration: 5.0,
    repeat: -1,
    yoyo: true,
    ease: 'sine.inOut'
  });

  // Slow frame drift tick loop
  let startTime = Date.now();
  const driftTimeline = gsap.ticker.add((time, deltaTime) => {
    const elapsed = (Date.now() - startTime) * 0.001; // in seconds
    const fhz = 0.05 * 2 * Math.PI;

    // Slow orbital drift around base anchor points
    for (let i = 0; i < numOuter; i++) {
      const p = outerParticles[i];
      const offset = 0.04;
      const angle = elapsed * fhz + p.phaseOffset;
      p.currentPos.x = p.anchor.x + Math.cos(angle) * offset;
      p.currentPos.y = p.anchor.y + Math.sin(angle) * offset;
      p.currentPos.z = p.anchor.z + Math.cos(angle * 0.5) * offset;
    }

    for (let i = 0; i < numCore; i++) {
      const p = coreParticles[i];
      const offset = 0.02; // narrower drift on core
      const angle = elapsed * fhz + p.phaseOffset;
      p.currentPos.x = p.anchor.x + Math.sin(angle) * offset;
      p.currentPos.y = p.anchor.y + Math.cos(angle) * offset;
      p.currentPos.z = p.anchor.z + Math.sin(angle * 0.5) * offset;
    }

    updateInstanceMatrices();
  });

  // Load animation
  const entranceTl = gsap.timeline();
  activeTimelines.push(entranceTl);

  // Stagger outer particles emergence outward from center
  const outerDelayedTweens = [];
  for (let i = 0; i < numOuter; i++) {
    const p = outerParticles[i];
    const dist = p.anchor.length();
    // Distance-based delay matching cubic-bezier curve
    const delay = Math.pow(dist / 5.0, 1.5) * 0.8;

    outerDelayedTweens.push(
      gsap.to(p, {
        scale: 1,
        duration: 1.4,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        delay: delay
      })
    );
  }

  // Core particles load quickly first
  for (let i = 0; i < numCore; i++) {
    const p = coreParticles[i];
    gsap.to(p, {
      scale: 1,
      duration: 0.8,
      ease: 'power3.out',
      delay: Math.random() * 0.2
    });
  }

  // --- PRIMITIVES INTEROP ---
  const configPrimitives = config.cinematicPrimitives ?? [];
  for (const prim of configPrimitives) {
    if (ctx.primitives[prim.name]) {
      const res = ctx.primitives[prim.name](group, prim.params);
      if (res) activePrimitives.push(res);
    }
  }

  // --- CLEANUP ---
  group.userData.cleanup = function() {
    activeTimelines.forEach((tl) => tl.kill());
    gsap.ticker.remove(driftTimeline);
    activePrimitives.forEach((prim) => {
      if (prim?.cleanup) prim.cleanup();
    });

    // Dipose geometries & materials
    backdropGeo.dispose();
    backdropMat.dispose();
    particleGeo.dispose();
    particleMat.dispose();
    coreMat.dispose();
    instancedMesh.dispose();
    coreInstancedMesh.dispose();
  };

  return group;
}
